#include <bits/stdc++.h>

using namespace std;

using LL = long long;

vector<LL> factor;

LL GCD(LL a, LL b) {
    return b == 0 ? a : GCD(b, a % b);
}

LL sol(LL x, LL y, const vector<LL>& f) {
    LL g = GCD(x, y);
    x /= g;
    y /= g;

    if (x == 1) return y;
    if (y == 0) return 0;

    LL min_d = numeric_limits<LL>::max();
    LL best_gcd = 1;

    for (LL divisor : f) {
        if (divisor > x || divisor > y) break;
        if (x % divisor != 0) continue;

        LL d = y % divisor;
        if (d <= min_d) {
            min_d = d;
            best_gcd = divisor;
        }
    }

    if (min_d == numeric_limits<LL>::max()) {
        return y;
    }

    return min_d + 1 + sol(x, y - min_d - best_gcd, f);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    LL x, y;
    cin >> x >> y;

    for (LL i = 2; i <= x / i; ++i) {
        if (x % i == 0) {
            factor.push_back(i);
            if (i != x / i) factor.push_back(x / i);
        }
    }
    if (x > 1) factor.push_back(x);

    sort(factor.begin(), factor.end());
    factor.erase(unique(factor.begin(), factor.end()), factor.end());

    cout << sol(x, y, factor) << '\n';
    return 0;
}

