#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 x, y;
    cin >> x >> y;

    vector<int64> primes;
    int64 n = x;

    for (int64 p = 2; p <= n / p; ++p) {
        if (n % p == 0) {
            primes.push_back(p);
            while (n % p == 0) n /= p;
        }
    }
    if (n > 1) primes.push_back(n);

    int64 answer = 0;

    while (y > 0) {
        int64 g = std::gcd(x, y);
        x /= g;
        y /= g;

        if (x == 1) {
            answer += y;
            break;
        }

        int64 steps = y;
        for (int64 p : primes) {
            if (x % p == 0) {
                steps = min(steps, y % p);
            }
        }

        answer += steps;
        y -= steps;
    }

    cout << answer << '\n';
    return 0;
}

